WITH matched_keys AS (SELECT region, id FROM stores INTERSECT SELECT region, id FROM stores WHERE region = 'South'), kept_rows AS (SELECT s.* FROM stores s INNER JOIN matched_keys k ON s.region = k.region AND s.id = k.id) SELECT DATE_TRUNC('MONTH', opened_date) AS activity_month, region, COUNT(DISTINCT region) AS distinct_regions, SUM(CASE WHEN region = 'North' THEN sqft ELSE 0 END) AS north_sqft, ROUND(SUM(sqft) / NULLIF(COUNT(CASE WHEN city = 'Bangkok' THEN 1 END), 0), 2) AS sqft_per_bangkok, APPROX_PERCENTILE(sqft, 0.95) AS sqft_p95, ROUND(AVG(sqft), 2) AS avg_sqft FROM kept_rows GROUP BY DATE_TRUNC('MONTH', opened_date), region;
